def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        base = 18.0 if hp > 4 else 42.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_prev_bids = []
    rich_urgent_prev_bids = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))
            opp_urgent = opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1
            if opp_urgent:
                urgent_prev_bids.append(float(bid))
                if opp.get('budget', 0) >= float(bid):
                    rich_urgent_prev_bids.append(float(bid))

    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    base = 32.0
    if loose_supply:
        base = 24.0
    elif tight_supply:
        base = 46.0

    if hp <= 2 or no_water >= 2:
        base = max(base, 92.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 68.0)
    elif hp >= 8 and no_water == 0 and loose_supply:
        base = min(base, 22.0)

    if rich_urgent_prev_bids:
        target = max(rich_urgent_prev_bids) + 2.0
        if hp <= 4 or no_water >= 1:
            base = max(base, target)
        else:
            base = max(base, min(target, 58.0))
    elif urgent_prev_bids:
        target = max(urgent_prev_bids) + 1.0
        if hp <= 4 or no_water >= 1:
            base = max(base, min(target, 85.0))
    elif prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev <= 60.0:
            base = max(base, highest_prev + 2.0)
        elif highest_prev >= 120.0 and hp > 4 and no_water == 0:
            base = min(base, 36.0)

    if day >= 8:
        if hp <= 4 or no_water >= 1:
            base += 10.0
        else:
            base += 4.0

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    TOTAL_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('bid') > 0:
            yesterday_bids.append(prev['bid'])

    competitive_yesterday_bids = [b for b in yesterday_bids if b >= DAILY_SALARY * 0.5]

    highest_prev_bid = 0
    if competitive_yesterday_bids:
        highest_prev_bid = max(competitive_yesterday_bids)

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']

    # Aggressive bidding if HP is critically low
    if my_current_hp <= 2:
        return min(my_current_budget, DAILY_SALARY * 1.1 + 10) 

    # High pressure if HP is low
    if my_current_hp <= 4:
        if highest_prev_bid > DAILY_SALARY * 0.8: 
            return min(my_current_budget, max(DAILY_SALARY * 0.95, highest_prev_bid + 5))
        else:
            return min(my_current_budget, DAILY_SALARY * 0.9)

    # Moderate HP, adjust based on previous bids
    if highest_prev_bid > DAILY_SALARY * 0.8: 
        # If it's late in the game and budget is good, be more aggressive
        if current_day >= TOTAL_DAYS - 2 and my_current_budget >= DAILY_SALARY * 2: 
            return min(my_current_budget, highest_prev_bid + 10)

        # Otherwise, try to win but with some budget conservation
        return min(my_current_budget, max(DAILY_SALARY * 0.75, highest_prev_bid + 2))

    elif highest_prev_bid > 0: 
        return min(my_current_budget, max(DAILY_SALARY * 0.6, highest_prev_bid + 1))

    else: 
        return min(my_current_budget, DAILY_SALARY * 0.65)
